import { PrismaClient } from "@prisma/client";
import { scryptSync, createDecipheriv } from "node:crypto";
import { Client } from "ssh2";

function deriveKey(){ return scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32); }
function decryptSecret(enc){
  if(!enc) return null;
  try{ const [i,t,d]=enc.split(":"); const dc=createDecipheriv("aes-256-gcm",deriveKey(),Buffer.from(i,"base64")); dc.setAuthTag(Buffer.from(t,"base64")); return Buffer.concat([dc.update(Buffer.from(d,"base64")),dc.final()]).toString("utf8"); }catch(e){ return null; }
}
const db=new PrismaClient();
const s=await db.server.findUnique({ where:{ id:"cmsecmdps0001hlp27ai6mr7c" } });
await db.$disconnect();
if(!s){ console.log("NO SERVER"); process.exit(1); }
console.error(`SERVER name=${s.name} host=${s.hostname} ip=${s.ipAddress}`);
const pw = decryptSecret(s.rootPasswordEnc) || s.rootPassword;
if(!pw){ console.log("NO PASSWORD"); process.exit(1); }

const CMD = process.argv[2];
const conn=new Client();
conn.on("ready",()=>{
  conn.exec(CMD,(err,stream)=>{
    if(err){ console.error(err); conn.end(); return; }
    stream.on("close",()=>conn.end()).on("data",d=>process.stdout.write(d)).stderr.on("data",d=>process.stderr.write(d));
  });
}).on("error",e=>{ console.error("SSH ERR",e.message); process.exit(1); })
.connect({ host:s.ipAddress||s.hostname, port:s.sshPort||22, username:"root", password:pw, readyTimeout:20000 });
EOF
